package com.energie.platform.service;
import com.energie.platform.dto.Dtos.*; import com.energie.platform.model.Profil; import com.energie.platform.repository.Repositories.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class AdminService {private final FormulaireRepository formulaires;private final VisiteurRepository visiteurs;private final RegionRepository regions;private final RendezVousService rdv;
 @Transactional(readOnly=true) public StatistiquesResponse statistiques(){long total=visiteurs.count(),sub=formulaires.countByDateSoumissionIsNotNull();Map<String,Long> byRegion=new LinkedHashMap<>();regions.findAll().forEach(r->byRegion.put(r.getNom(),visiteurs.findAll().stream().filter(v->v.getRegion()!=null&&v.getRegion().getId().equals(r.getId())).count()));return new StatistiquesResponse(sub,total,total==0?0:(sub*100.0/total),visiteurs.countByProfil(Profil.PARTICULIER),visiteurs.countByProfil(Profil.SOCIETE),byRegion,rdv.aVenir());}
 @Transactional(readOnly=true) public String exportCsv(List<FormulaireResponse> list){StringBuilder b=new StringBuilder("id,profil,visiteurId,etape,dateSoumission,reponses\n");for(FormulaireResponse f:list)b.append(f.id()).append(',').append(f.profil()).append(',').append(f.visiteurId()).append(',').append(f.etapeActuelle()).append(',').append(f.dateSoumission()==null?"":f.dateSoumission()).append(",\"").append(f.reponses().toString().replace("\"","\"\"")).append("\"\n");return b.toString();}
}
